// Üretilen dosya: tool/ozgun/uret.py. Tarih · Diplomasi tarihi: antlaşmalar, kongreler, ittifaklar ve uluslararası kuruluşların doğuşu (Kadeş, Vestfalya, Karlofça, Viyana Kongresi, Lozan, BM, NATO kuruluşu) (kolay).
const ozHistory18Kolay = <(String, String, List<String>, String)>[
  ('Tarihte yazılı olarak imzalanmış en eski barış antlaşması olarak kabul edilen Kadeş Antlaşması hangi iki devlet arasında yapılmıştır?', 'Mısır ve Hitit', ['Asur ve Babil', 'Sümer ve Elam', 'Pers ve Yunan'], 'Kadeş Antlaşması MÖ 1280 civarında Kuzey Suriye hakimiyeti için savaşan Mısır ve Hitit imparatorlukları arasında imzalanmıştır.'),
  ('Kadeş Antlaşması\'nın kil tablet üzerine çivi yazısıyla kazınmış orijinal nüshalarından biri Anadolu\'daki hangi antik kent kazılarında bulunmuştur?', 'Boğazköy (Hattuşa)', ['Çatalhöyük (Konya)', 'Alacahöyük (Çorum)', 'Kültepe (Kayseri)'], 'Hitit İmparatorluğu\'nun başkenti olan Hattuşa\'da (Boğazköy) yapılan kazılarda Kadeş Antlaşması\'nın Akadca çivi yazılı kil tableti ortaya çıkarılmıştır.'),
  ('Birleşmiş Milletler Genel Merkezi binasının duvarında barış diplomasisinin tarihsel sembolü olarak büyütülmüş kopyası sergilenen İlk Çağ antlaşması hangisidir?', 'Kadeş Antlaşması', ['Kallias Barışı', 'Apameia Antlaşması', 'Dardanos Barışı'], 'New York\'taki Birleşmiş Milletler binasında Kadeş Antlaşması\'nın bakır röprodüksiyonu uluslararası barışın en eski yazılı simgesi olarak asılıdır.'),
  ('Roma İmparatorluğu\'nda Hristiyanlığa inanç özgürlüğü tanıyan 313 tarihli Milano Fermanı\'nı Batı Roma İmparatoru I. Konstantin ile birlikte yayımlayan Doğu Roma İmparatoru kimdir?', 'Licinius', ['Diocletianus', 'Galerius', 'Theodosius'], '313 yılında Milano\'da bir araya gelen Konstantin ve Licinius, imparatorluk genelinde Hristiyanlara yönelik kovuşturmaları sonlandıran ortak kararı ilan etmiştir.'),
  ('434 yılında Doğu Roma (Bizans) İmparatorluğu\'nu ağır vergiye bağlayan Margus Antlaşması\'nı imzalayan Avrupa Hun hükümdarı kimdir?', 'Attila (kardeşi Bleda ile birlikte)', ['Balamir (oğulları ile birlikte)', 'Uldız (Batı ordusu komutanıyla)', 'Rua (Tuna boyu beyleriyle)'], 'Rua\'nın ölümünden sonra başa geçen Attila ve Bleda, Konstantia (Margus) surları önünde at sırtında Doğu Roma elçilerine antlaşma şartlarını kabul ettirmiştir.'),
  ('843 yılında Karolenj İmparatorluğu\'nu Şarlman\'ın üç torunu arasında paylaştıran ve Batı Avrupa\'nın siyasi haritasının temellerini atan antlaşma hangisidir?', 'Verdun Antlaşması', ['Mersen Antlaşması', 'Ribemont Antlaşması', 'Aachen Barışı'], '843 Verdun Antlaşması ile İmparator Dindar Ludwig\'in oğulları I. Lothar, Alman Ludwig ve Kel Karl imparatorluğu üç ayrı krallığa bölmüştür.'),
  ('1215 yılında İngiltere\'de Kral Yurtsuz John\'un yetkilerini ilk kez yazılı bir belgeyle sınırlandıran tarihsel sözleşme hangisidir?', 'Magna Carta Libertatum (Büyük Özgürlük Fermanı)', ['Petition of Right (Haklar Dilekçesi)', 'Bill of Rights (Haklar Bildirgesi)', 'Habeas Corpus Yasası'], '15 Haziran 1215\'te Runnymede çayırında imzalanan Magna Carta, İngiliz anayasal monarşi geleneğinin başlangıç noktası kabul edilir.'),
  ('1494 yılında İspanya ve Portekiz arasında Yeni Dünya\'daki keşfedilen toprakları Papa\'nın hakemliğinde boylam çizgisiyle ikiye ayıran antlaşma hangisidir?', 'Tordesillas Antlaşması', ['Utrecht Antlaşması', 'Pireneler Antlaşması', 'Cateau-Cambresis Antlaşması'], 'Tordesillas Antlaşması ile Yeşil Burun Adaları\'nın batısından geçen hat sınır kabul edilerek doğusu Portekiz\'e (Brezilya dahil), batısı İspanya\'ya bırakılmıştır.'),
  ('Almanya\'daki Reform hareketleri sonucunda Katolikler ile Protestan (Lüterci) prensler arasındaki mezhep savaşlarını 1555 yılında sonlandıran antlaşma hangisidir?', 'Augsburg Barışı', ['Nantes Fermanı', 'Worms Diyeti', 'Passau Sözleşmesi'], '25 Eylül 1555\'te Kutsal Roma Diyeti\'nde kabul edilen Augsburg Barışı, Kutsal Roma İmparatorluğu içinde Lüterciliğin hukuki varlığını resmen tanımıştır.'),
  ('Avrupa\'da 1618-1648 yılları arasında süren yıkıcı Otuz Yıl Savaşları\'nı sona erdiren ve modern uluslararası ilişkiler sisteminin başlangıcı sayılan antlaşmalar bütünü hangisidir?', 'Vestfalya Barışı', ['Viyana Kongresi', 'Utrecht Barışı', 'Aachen Antlaşması'], '1648 yılında imzalanan Vestfalya Barışı, din temelli evrensel imparatorluk iddiasını bitirip egemen devletler sistemini kurmuştur.'),
  ('1648 Vestfalya Antlaşmaları ile İspanya\'ya karşı yürüttüğü Seksen Yıl Savaşı sonucunda bağımsızlığı uluslararası alanda resmen tanınan devlet hangisidir?', 'Birleşik Hollanda Cumhuriyeti', ['Belçika Krallığı', 'Lüksemburg Büyük Dukalığı', 'Portekiz Cumhuriyeti'], 'Ocak 1648\'deki Münster Antlaşması ile İspanya, Birleşik Eyaletler\'in (Hollanda) tam bağımsızlığını resmen tanımıştır.'),
  ('Osmanlı Devleti\'nin Avusturya üzerinde 1533 İstanbul (İbrahim Paşa) Antlaşması ile kurduğu diplomatik ve protokol üstünlüğünü sona erdiren 1606 tarihli antlaşma hangisidir?', 'Zitvatorok Antlaşması', ['Vasvar Antlaşması', 'Edirne-Segedin Antlaşması', 'Bucaş Antlaşması'], '1593-1606 Uzun Türk Savaşı sonunda imzalanan Zitvatorok Antlaşması, Osmanlı-Avusturya ilişkilerinde eşitlik dönemini başlatmıştır.'),
  ('1606 Zitvatorok Antlaşması hangi Osmanlı padişahı döneminde imzalanmıştır?', 'I. Ahmed', ['III. Murad', 'II. Osman', 'IV. Murad'], '1603\'te tahta çıkan Sultan I. Ahmed döneminde Kuyucu Murad Paşa\'nın girişimleriyle Zitvatorok Antlaşması imzalanmıştır.'),
  ('1639 yılında Osmanlı Devleti ile Safevi Devleti arasında imzalanan ve bugünkü Türkiye-İran kara sınırının büyük ölçüde temelini çizen antlaşma hangisidir?', 'Kasr-ı Şirin Antlaşması', ['Ferhat Paşa Antlaşması', 'Amasya Antlaşması', 'Erzurum Antlaşması'], '17 Mayıs 1639\'da imzalanan Kasr-ı Şirin Antlaşması ile çizilen sınır hattı, küçük revizyonlar dışında yüzyıllar boyunca korunmuştur.'),
  ('1639 Kasr-ı Şirin Antlaşması\'na zemin hazırlayan başarılı Revan ve Bağdat seferlerini bizzat komuta eden Osmanlı padişahı kimdir?', 'IV. Murad', ['I. Süleyman', 'Yavuz Sultan Selim', 'III. Selim'], 'Sultan IV. Murad 1635\'te Revan\'ı ve 1638\'de Bağdat\'ı bizzat ordunun başında geri alarak Safevi yönetimini Kasr-ı Şirin barışına razı etmiştir.'),
  ('Osmanlı Devleti\'nin Batı\'da ilk kez büyük çapta toprak kaybettiği ve duraklama döneminden gerileme sürecine geçişinin dönüm noktası sayılan 1699 tarihli antlaşma hangisidir?', 'Karlofça Antlaşması', ['Pasarofça Antlaşması', 'Belgrad Antlaşması', 'Küçük Kaynarca Antlaşması'], '1683 II. Viyana Kuşatması bozgunuyla başlayan Kutsal İttifak Savaşları sonunda 26 Ocak 1699\'da Karlofça Antlaşması imzalanmıştır.'),
  ('1699 Karlofça Antlaşması uyarınca Tımışvar (Temeşvar) eyaleti ve Banat yaylası hariç tüm Macaristan ile Erdel toprakları hangi devlete bırakılmıştır?', 'Avusturya (Habsburg) İmparatorluğu\'na', ['Lehistan-Litvanya Birliği\'ne', 'Venedik Cumhuriyeti\'ne', 'Prusya Krallığı\'na'], 'Osmanlı\'nın Kanuni döneminden beri elinde tuttuğu Orta Macaristan ve Erdel üzerindeki hakimiyeti Karlofça ile sona ererek Avusturya\'ya geçmiştir.'),
  ('1718 yılında Osmanlı Devleti\'nin Avusturya ve Venedik ile imzaladığı, Batı\'nın üstünlüğünü kabul ederek Lale Devri reformlarına yönelmesine neden olan antlaşma hangisidir?', 'Pasarofça Antlaşması', ['Prut Antlaşması', 'Belgrad Antlaşması', 'Ziştovi Antlaşması'], 'Petervaradin yenilgisi ve Belgrad\'ın kaybı sonrasında 21 Temmuz 1718\'de imzalanan Pasarofça Antlaşması ile Osmanlı Batı yönlü barış ve yenileşme politikasına girmiştir.'),
  ('Kadeş Antlaşması\'nın Mısır hiyeroglifleriyle taş duvarlara kazınmış metni Mısır\'daki hangi ünlü tapınak kompleksinde günümüze ulaşmıştır?', 'Karnak ve Ramesseum Tapınaklarında', ['İskenderiye Feneri ve Kütüphanesinde', 'Gize Kefren Piramidi iç odasında', 'Edfu Horus Tapınağı mahzenlerinde'], 'II. Ramses, Kadeş Antlaşması metnini Teb\'deki Karnak Amon Tapınağı ile Ramesseum duvarlarına hiyeroglif yazıyla kazıtmıştır.'),
  ('MÖ 421 yılında Atina ile Sparta arasında Peloponnes Savaşları\'nın ilk aşamasını geçici olarak durduran ve adını Atinalı devlet adamından alan barış antlaşması hangisidir?', 'Nikias Barışı', ['Perikles Antlaşması', 'Solon Uzlaşması', 'Kleistenes Paktı'], 'Ellişer yıllık bir süreyi kapsamak üzere MÖ 421\'de imzalanan Nikias Barışı, savaş öncesi durumu geri getirmeyi hedeflemiş ancak kısa sürede bozulmuştur.'),
  ('313 Milano Fermanı öncesinde Roma İmparatorluğu\'nda Hristiyanlara yönelik en sert ve sistematik kovuşturmayı 303 yılında başlatan "Tetrarşi (Dörtlü Yönetim)" kurucusu imparator kimdir?', 'Diocletianus', ['Marcus Aurelius', 'Septimius Severus', 'Konstantius Chlorus'], 'Diocletianus 303\'ten itibaren çıkardığı fermanlarla kiliselerin yıkılmasını ve kutsal metinlerin yakılmasını emretmiş, 313 Milano Fermanı bu baskı dönemini kesin olarak kapatmıştır.'),
  ('843 Verdun Antlaşması\'nda Karolenj İmparatorluğu topraklarından bugünkü Fransa\'nın çekirdeğini oluşturan "Batı Frank Krallığı" kimin payına düşmüştür?', 'Kel Karl (II. Charles)', ['Alman Ludwig (II. Ludwig)', 'I. Lothar', 'Kısa Pepin'], 'Verdun paylaşımında Batı Frank topraklarını Kel Karl, Doğu Frank (Almanya) topraklarını Alman Ludwig, İtalya ve orta kuşağı ise I. Lothar almıştır.'),
  ('1215 Magna Carta\'nın imzalanmasından sonra İngiltere\'de kralın vergi toplama yetkisini denetlemek üzere baronlar, din adamları ve şehir temsilcilerinin katılımıyla 13. yüzyıl sonlarında kurumsallaşan meclis hangisidir?', 'İngiliz Parlamentosu', ['Genel Katmanlar Meclisi', 'İmparatorluk Diyeti', 'Kastilya Cortes Meclisi'], '1265 Simon de Montfort meclisi ve 1295 I. Edward\'ın "Model Parlamentosu", Magna Carta\'daki ortak konsey rızası ilkesinin parlamenter kuruma dönüşmüş halidir.'),
  ('1444 yılında Osmanlı Padişahı II. Murad\'ın Macar-Leh ordusuyla imzaladığı ve ardından tahtı on iki yaşındaki oğlu II. Mehmed\'e bıraktığı on yıllık barış antlaşması hangisidir?', 'Edirne-Segedin Antlaşması', ['İbrahim Paşa Antlaşması', 'Çamurlu Antlaşması', 'Ploşnik Antlaşması'], 'Balkanlar\'da barışı güvenceye almak isteyen II. Murad 1444\'te Edirne-Segedin Antlaşması\'nı imzalamış, ancak Haçlıların yemini bozmasıyla aynı yıl Varna Savaşı yaşanmıştır.'),
  ('1648 Vestfalya Barışı\'na giden süreçte Otuz Yıl Savaşları\'nı 1618 yılında başlatan ve Habsburgların elçilerinin pencereden atılmasıyla tarihe geçen diplomatik kriz hangisidir?', 'Prag Pencereden Atma Olayı', ['Aziz Bartolomeus Yortusu Katliamı', 'Barut Komplosu Girişimi', 'Canossa Kefaret Yürüyüşü'], 'Bohemyalı Protestan soyluların Mayıs 1618\'de Prag Kalesi\'nde İmparatorluk naiblerini pencereden aşağı atması Otuz Yıl Savaşları\'nın kıvılcımı olmuştur.'),
  ('1648 Vestfalya Barışı Avrupa kıtasının tamamına yakınından elçi ve temsilcilerin katılımıyla hazırlandığı için diplomasi tarihinde hangi ilk özelliğe sahip toplantı kabul edilir?', 'Çok taraflı ilk büyük Avrupa barış kongresi olmasına', ['Telgraf hatlarıyla canlı yayınlanan ilk uluslararası zirve olmasına', 'Devlet başkanlarının tamamının bizzat katıldığı ilk toplantı olmasına', 'Fransızcanın tek resmi dil olarak kullanıldığı ilk kongre olmasına'], 'Yüzden fazla heyetin yıllarca müzakere yürüttüğü Münster ve Osnabrück görüşmeleri, Avrupa\'daki ilk modern çok taraflı diplomasi kongresidir (dil olarak hala Latince ağırlıklıydı).'),
  ('1606 Zitvatorok Antlaşması öncesinde Osmanlı ordusunun Avusturya cephesinde kazandığı son büyük meydan muharebesi olan 1596 tarihli savaş hangisidir?', 'Haçova Meydan Muharebesi', ['Mohaç Meydan Muharebesi', 'Çaldıran Meydan Muharebesi', 'Mezokövesd Çarpışması'], 'III. Mehmed\'in ordunun başında çıktığı Eğri Seferi sırasında kazanılan 1596 Haçova Zaferi, Osmanlı\'nın Orta Avrupa\'daki son büyük meydan savaşı zaferidir.'),
  ('1683 II. Viyana Kuşatması\'nın başarısızlıkla sonuçlanmasının ardından Papa XI. Innocentius\'un çağrısıyla Osmanlı\'ya karşı bir araya gelen Avrupa koalisyonuna ne ad verilmiştir?', 'Kutsal İttifak', ['Üçlü İtilaf Bloğu', 'Ren Konfederasyonu', 'Schmalkalden Birliği'], 'Avusturya, Lehistan, Venedik, Malta ve sonradan Rusya\'nın katılımıyla 1684\'te kurulan Kutsal İttifak, Osmanlı\'yı Avrupa\'dan atmak amacıyla on altı yıl savaşmıştır.'),
  ('1699 Karlofça Antlaşması imzalandığı sırada Osmanlı tahtında hangi padişah bulunmaktaydı?', 'II. Mustafa', ['III. Ahmed', 'IV. Mehmed', 'I. Mahmud'], '1695-1703 yılları arasında saltanat süren Sultan II. Mustafa döneminde Karlofça Antlaşması imzalanmış, ardından yaşanan 1703 Edirne Vakası ile tahta III. Ahmed geçmiştir.'),
  ('1718 Pasarofça Antlaşması hangi Osmanlı padişahı ve sadrazamı ikilisinin yönetiminde imzalanarak Lale Devri\'ni başlatmıştır?', 'Padişah III. Ahmed ve Sadrazam Nevşehirli Damat İbrahim Paşa', ['Padişah I. Abdülhamid ve Sadrazam Halil Hamid Paşa', 'Padişah III. Selim ve Sadrazam Koca Yusuf Paşa', 'Padişah II. Mahmud ve Sadrazam Alemdar Mustafa Paşa'], 'III. Ahmed ve Sadrazam Nevşehirli Damat İbrahim Paşa, 1718 Pasarofça Antlaşması ile Batı cephesinde barışı sağlayarak 1730\'a dek sürecek Lale Devri ıslahatlarını başlatmıştır.'),
  ('Diplomasi tarihinde antlaşmaların bağlayıcılığını ifade eden ve "antlaşmalara sadık kalınmalıdır / verilen söz tutulmalıdır" anlamına gelen temel uluslararası hukuk ilkesi hangisidir?', 'Pacta sunt servanda (Ahde vefa)', ['Cuius regio, eius religio', 'Uti possidetis (Elde tutulan mülktür)', 'Casus belli (Savaş nedeni)'], 'İlk Çağ\'daki Kadeş yeminlerinden modern Vestfalya hukukuna kadar tüm antlaşmalar hukukunun temel taşı "pacta sunt servanda" yani ahde vefa ilkesidir.'),
  ('Osmanlı diplomasi belgelerinde yabancı devlet elçilerinin ülkede güvenli şekilde seyahat etmesini ve dokunulmazlığını güvence altına alan İslam devletler hukuku kavramı hangisidir?', 'Aman (Eman) sistemi', ['Müsadere sistemi', 'İltizam sistemi', 'Gedik sistemi'], 'İslam ve Osmanlı hukukunda "elçiye zeval olmaz" anlayışı çerçevesinde yabancı diplomatlara ve tüccarlara can ve mal güvenliği sağlayan "eman" statüsü tanınırdı.'),
  ('Bugünkü Türkiye Cumhuriyeti\'nin en eski ve coğrafi olarak en az değişikliğe uğramış kara sınırı, 17. yüzyılda imzalanan hangi antlaşmaya dayanmaktadır?', '1639 Kasr-ı Şirin Antlaşması\'na', ['1606 Zitvatorok Antlaşması\'na', '1699 Karlofça Antlaşması\'na', '1718 Pasarofça Antlaşması\'na'], 'Türkiye-İran sınırı, 1639 Kasr-ı Şirin Antlaşması\'nda Zağros Dağları su bölümü hattı esas alınarak çizilmiş ve yaklaşık dört asırdır korunmuştur.'),
  ('1699 Karlofça Antlaşması ile Osmanlı Devleti\'nin Orta Avrupa\'daki yüz yetmiş yılı aşkın Macaristan hakimiyetinin sona ermesi, Balkanlar\'daki Osmanlı savunma hattını hangi nehir boyuna geriletmiştir?', 'Tuna ve Sava nehirleri hattına', ['Ren ve Elbe nehirleri hattına', 'Fırat ve Dicle nehirleri hattına', 'Volga ve Don nehirleri hattına'], 'Macaristan\'ın elden çıkmasıyla Osmanlı\'nın Avrupa\'daki doğal savunma sınırı Tuna ve Sava nehirleri ile Belgrad kilit noktasına çekilmiş, 1718 Pasarofça\'da ise Belgrad da geçici olarak kaybedilmiştir.'),
  ('1774 yılında Osmanlı Devleti ile Rusya arasında imzalanan ve Kırım\'a siyasi bağımsızlık tanıyan antlaşma hangisidir?', 'Küçük Kaynarca Antlaşması', ['Belgrad Barış Antlaşması', 'Ziştovi Barış Antlaşması', 'Bükreş Barış Antlaşması'], '1768-1774 Osmanlı-Rus Savaşı sonunda imzalanan Küçük Kaynarca Antlaşması ile Kırım Hanlığı Osmanlı\'dan ayrılarak bağımsız olmuştur.'),
  ('Osmanlı Devleti\'nin Kırım\'ın Rusya\'ya ait olduğunu resmen kabul ettiği 1792 tarihli antlaşma hangisidir?', 'Yaş Antlaşması', ['Prut Antlaşması', 'Pasarofça Antlaşması', 'Edirne Antlaşması'], '1787-1792 Osmanlı-Rus Savaşı sonrasında imzalanan Yaş Antlaşması ile Kırım\'ın Rusya\'ya ilhakı kesinleşmiştir.'),
  ('Küçük Kaynarca Antlaşması\'nın Karadeniz\'in statüsü üzerinde yarattığı en önemli değişiklik nedir?', 'Karadeniz\'in bir Türk gölü olma özelliğini kaybederek Rus ticaret gemilerine açılması', ['Karadeniz kıyısındaki tüm limanların uluslararası serbest ticaret bölgesi ilan edilmesi', 'Boğazların yönetimini denetlemek üzere çok uluslu bir boğazlar komisyonu kurulması', 'İngiliz ve Fransız savaş donanmalarına Karadeniz\'de daimi üs kurma izni verilmesi'], 'Rus ticaret gemilerinin Karadeniz ve Akdeniz\'de serbestçe dolaşma hakkı elde etmesiyle Karadeniz Türk gölü olmaktan çıkmıştır.'),
  ('Napolyon Savaşları sonrasında Avrupa\'nın siyasi haritasını yeniden çizmek amacıyla 1814-1815 yıllarında toplanan uluslararası kongre hangisidir?', 'Viyana Kongresi', ['Aachen Kongresi', 'Verona Kongresi', 'Troppau Kongresi'], 'Napolyon\'un yenilgisinin ardından Avrupa güç dengesini yeniden kurmak üzere büyük devletler Viyana Kongresi\'nde bir araya gelmiştir.'),
  ('1815 Viyana Kongresi\'ne başkanlık eden ve kurulan muhafazakar diplomatik düzene adını veren Avusturya devlet adamı kimdir?', 'Prens Klemens von Metternich', ['Prens Otto von Bismarck', 'Kont Camillo di Cavour', 'Lord Palmerston'], 'Avusturya Başbakanı ve Dışişleri Bakanı Metternich, kongreyi yönlendirerek ihtilal karşıtı muhafazakar düzenin mimarı olmuştur.'),
  ('1815 Viyana Kongresi sonrasında büyük devletlerin Avrupa\'daki güç dengesini ve statükoyu ortak danışmalarla koruma sistemine ne ad verilir?', 'Avrupa Uyumu', ['Kıta Ablukası Sistemi', 'Silahlı Tarafsızlık Birliği', 'Dehşet Dengesi Doktrini'], 'Avrupa Uyumu (Concert of Europe), 19. yüzyılda büyük güçlerin krizleri kongre diplomasisiyle çözme mekanizmasını tanımlar.'),
  ('1827 yılında İngiltere, Fransa ve Rusya\'nın birleşik donanmasının Osmanlı-Mısır donanmasını imha ettiği deniz baskını hangisidir?', 'Navarin Baskını', ['Çeşme Baskını', 'Sinop Baskını', 'Preveze Deniz Muharebesi'], 'Yunan isyanı sırasında Osmanlı yönetimini ateşkes ve özerkliğe zorlamak isteyen üç devlet Navarin\'de Osmanlı-Mısır donanmasını yakmıştır.'),
  ('Boğazların statüsünü ilk kez uluslararası bir sözleşmeye bağlayan ve barış zamanında yabancı savaş gemilerine kapalı olmasını kararlaştıran 1841 tarihli belge hangisidir?', 'Londra Boğazlar Sözleşmesi', ['Paris Boğazlar Mukavelesi', 'Berlin Boğazlar Protokolü', 'Viyana Deniz Hukuku Beyannamesi'], 'Hünkar İskelesi\'nin süresi dolunca imzalanan 1841 Londra Boğazlar Sözleşmesi ile Rusya\'nın Boğazlar üzerindeki üstünlüğü sona ermiştir.'),
  ('1853-1856 Kırım Savaşı öncesinde Rus Çarı I. Nikolay\'ın İngiltere\'ye Osmanlı topraklarını paylaşma teklifinde bulunurken Osmanlı için kullandığı ünlü tabir nedir?', 'Hasta Adam', ['Yalnız Kartal', 'Demir Perde', 'Uyuyan Dev'], 'Çar I. Nikolay, 1853\'te İngiliz elçisi Seymour ile görüşmesinde Osmanlı İmparatorluğu\'nu "kollarımızda ölmek üzere olan hasta adam" olarak nitelemiştir.'),
  ('Kırım Savaşı sırasında 30 Kasım 1853\'te Rus donanmasının Karadeniz\'deki Osmanlı filosunu imha ettiği olay hangisidir?', 'Sinop Baskını', ['Çeşme Baskını', 'Navarin Baskını', 'Preveze Baskını'], 'Sinop Baskını\'nın ardından İngiltere ve Fransa, Rusya\'nın Akdeniz\'e inmesini önlemek amacıyla Osmanlı\'nın yanında savaşa girmiştir.'),
  ('1853-1856 Kırım Savaşı\'nı sona erdiren ve Osmanlı Devleti\'nin bir Avrupa devleti sayılmasını kararlaştıran antlaşma hangisidir?', 'Paris Antlaşması (1856)', ['Berlin Antlaşması (1878)', 'Edirne Antlaşması (1829)', 'Londra Antlaşması (1840)'], '30 Mart 1856 tarihli Paris Antlaşması ile Osmanlı Devleti ilk kez Avrupa devletler hukukundan ve Avrupa Uyumu\'ndan yararlanma hakkı kazanmıştır.'),
  ('Osmanlı Devleti dış borçlanma tarihinde ilk kez hangi savaş sırasında (1854 yılında) İngiltere\'den dış borç almıştır?', 'Kırım Savaşı', ['93 Harbi', 'Trablusgarp Savaşı', 'Birinci Balkan Savaşı'], 'Artan savaş masraflarını karşılayamayan Osmanlı hazinesi, ilk dış borcunu Kırım Savaşı esnasında 1854\'te İngiltere\'den almıştır.'),
  ('Belçika\'nın Birleşik Hollanda Krallığı\'ndan ayrılarak bağımsızlığını kazanması ve "daimi tarafsız devlet" sayılması hangi yıllardaki ihtilal ve konferans süreciyle gerçekleşmiştir?', '1830 İhtilali ve 1831-1839 Londra Konferansı kararlarıyla', ['1789 Fransız İhtilali ve 1797 Campo Formio Antlaşması\'yla', '1870 Sedan Savaşı ve 1871 Frankfurt Antlaşması\'yla', '1853 Kırım Savaşı ve 1856 Paris Antlaşması\'yla'], '1830\'da ayaklanan Belçika\'nın bağımsızlığı ve tarafsızlığı büyük güçlerce Londra\'da tanınarak Viyana haritasında önemli bir revizyon yapılmıştır.'),
  ('19. yüzyılın ikinci yarısında "Kan ve Demir" politikasıyla Almanya\'nın siyasi birliğini sağlayan Prusya Başbakanı kimdir?', 'Otto von Bismarck', ['Klemens von Metternich', 'Helmuth von Moltke', 'Theobald von Bethmann Hollweg'], '1862\'de Prusya Başbakanı olan Bismarck, Danimarka, Avusturya ve Fransa savaşlarıyla 1871\'de Alman İmparatorluğu\'nu kurmuştur.'),
  ('1871 yılında Alman İmparatorluğu\'nun kuruluşunun ilan edildiği, sembolik önemi Fransız-Alman rekabetini derinleştiren mekan neresidir?', 'Versay Sarayı Aynalı Salon', ['Viyana Schönbrunn Sarayı', 'Berlin Sanssouci Sarayı', 'Frankfurt Aziz Paul Kilisesi'], 'Fransa\'nın yenilgisinin ardından I. Wilhelm\'in Versay Aynalı Salon\'da Alman İmparatoru ilan edilmesi Fransız ulusal gururunda derin iz bırakmıştır.'),
  ('1870 yılında Fransız koruma birliklerinin çekilmesi üzerine Roma\'nın alınmasıyla siyasi birliğini tamamlayan Avrupa devleti hangisidir?', 'İtalya Krallığı', ['Yunanistan Krallığı', 'Romanya Krallığı', 'İspanya Krallığı'], 'Fransa-Prusya Savaşı nedeniyle Fransız askerleri Roma\'dan çekilince İtalyan birlikleri 1870\'te Roma\'ya girerek birliği tamamlamıştır.'),
  ('19. yüzyılın ikinci yarısında Rusya\'nın tüm Slav topluluklarını kendi liderliği altında birleştirme ve Balkanlar üzerinden sıcak denizlere inme politikasına ne ad verilir?', 'Panslavizm', ['Pangermenizm', 'Merkantilizm', 'İrredantizm'], 'Rusya, Kırım Savaşı\'ndan sonra Balkanlar\'da Ortodoksluk koruyuculuğunun yanı sıra etnik temelli Panslavizm politikasına ağırlık vermiştir.'),
  ('1877-1878 Osmanlı-Rus Savaşı (93 Harbi) sonunda 3 Mart 1878\'de imzalanan ancak büyük devletlerin itirazı nedeniyle yürürlüğe giremeyen ölü doğmuş antlaşma hangisidir?', 'Ayastefanos (Yeşilköy) Antlaşması', ['Sevr Antlaşması', 'Hünkar İskelesi Antlaşması', 'Küçük Kaynarca Antlaşması'], 'Rus ordularının Yeşilköy\'e kadar ilerlemesi üzerine imzalanan Ayastefanos Antlaşması, Avrupa güç dengesini bozduğu için Berlin Antlaşması ile değiştirilmiştir.'),
  ('1878 yılında Ayastefanos Antlaşması\'nı gözden geçirmek üzere "dürüst arabulucu (ehrlicher Makler)" sıfatıyla Berlin Kongresi\'ne ev sahipliği ve başkanlık yapan devlet adamı kimdir?', 'Otto von Bismarck', ['Benjamin Disraeli', 'Aleksandr Gorçakov', 'Gyula Andrássy'], 'Alman Şansölyesi Bismarck, Balkanlar\'da Almanya\'nın doğrudan çıkarı olmadığını belirterek büyük güçler arası savaşı önlemek için kongreyi Berlin\'de toplamıştır.'),
  ('13 Temmuz 1878\'de imzalanan Berlin Antlaşması ile Osmanlı Devleti\'nden ayrılarak tam bağımsızlığı uluslararası alanda tanınan üç Balkan devleti hangileridir?', 'Sırbistan, Karadağ ve Romanya', ['Yunanistan, Bulgaristan ve Arnavutluk', 'Bosna, Hersek ve Makedonya', 'Hırvatistan, Slovenya ve Eflak'], 'Berlin Antlaşması ile Sırbistan, Karadağ ve Romanya bağımsız devlet statüsü kazanmıştır.'),
  ('1879 yılında Bismarck\'ın Rus tehdidine karşı Orta Avrupa güvenliğini sağlamak amacıyla Almanya ile hangi devlet arasında "İkili İttifak" imzalanmıştır?', 'Avusturya-Macaristan İmparatorluğu', ['İtalya Krallığı', 'Osmanlı İmparatorluğu', 'İngiltere Krallığı'], '7 Ekim 1879\'da Almanya ile Avusturya-Macaristan arasında Rusya saldırısına karşı imzalanan gizli İkili İttifak, Birinci Dünya Savaşı\'na kadar süren bloklaşmanın çekirdeğini oluşturmuştur.'),
  ('20 Mayıs 1882 tarihinde Almanya, Avusturya-Macaristan ve İtalya arasında imzalanan savunma anlaşmasıyla kurulan askeri-siyasi blok hangisidir?', 'Üçlü İttifak (Dreibund)', ['Üçlü İtilaf (Triple Entente)', 'Kutsal İttifak (Holy Alliance)', 'Balkan Antantı'], 'İtalya\'nın 1882\'de Almanya ve Avusturya-Macaristan\'ın yanına katılmasıyla Üçlü İttifak bloğu resmen kurulmuştur.'),
  ('Bismarck\'ın en büyük korkusu olan "iki cepheli savaş" riskini gerçeğe dönüştürerek 1894 yılında kesinleşen askeri ittifak hangi iki devlet arasında kurulmuştur?', 'Fransa ve Rusya', ['İngiltere ve Japonya', 'İtalya ve İspanya', 'Avusturya ve Osmanlı'], '1891\'de siyasi yakınlaşmayla başlayan ve 1892 askeri sözleşmesinin 1894\'te onaylanmasıyla yürürlüğe giren Fransız-Rus İttifakı, Fransa\'yı yalnızlıktan kurtarmıştır.'),
  ('19. yüzyılın büyük bölümünde İngiltere\'nin Kıta Avrupası\'ndaki barış zamanı kalıcı askeri ittifaklardan uzak durup deniz üstünlüğüne ve güç dengesine dayanma politikasına ne ad verilir?', 'Muhteşem Yalnızlık (Splendid Isolation)', ['Açık Kapı Politikası (Open Door Policy)', 'Yatıştırma Politikası (Appeasement)', 'Çevreleme Politikası (Containment)'], 'İngiltere, Kıta Avrupası\'nda tek bir gücün hegemonya kurmasını engellemek dışında bağlayıcı ittifaklara girmeme siyasetini "Splendid Isolation" olarak adlandırmıştır.'),
  ('İngiltere\'nin "Muhteşem Yalnızlık" politikasından resmen vazgeçerek 1902 yılında Uzak Doğu\'da Rus yayılmacılığını dengelemek üzere imzaladığı ilk ittifak hangi devletledir?', 'Japonya İmparatorluğu', ['Amerika Birleşik Devletleri', 'Çin İmparatorluğu', 'Hollanda Krallığı'], '1902 İngiliz-Japon İttifakı ile İngiltere, Uzak Doğu\'daki deniz yükünü hafifleterek donanmasını Kuzey Denizi\'nde Almanya\'ya karşı yoğunlaştırma imkanı bulmuştur.'),
  ('8 Nisan 1904 tarihinde İngiltere ile Fransa arasında sömürge anlaşmazlıklarını çözerek kurulan dostluk mutabakatına ne ad verilir?', 'Entente Cordiale', ['Kutsal İttifak', 'Üç İmparatorlar Ligi', 'Küçük Antant'], '1904 Entente Cordiale antlaşması resmi bir askeri ittifak olmasa da yüzyıllık İngiliz-Fransız sömürge rekabetini bitirerek Üçlü İtilaf\'ın temelini atmıştır.'),
  ('31 Ağustos 1907\'de imzalanan ve Üçlü İtilaf (İngiltere, Fransa, Rusya) bloğunun oluşumunu tamamlayan antlaşma hangi iki devlet arasındadır?', 'İngiltere ve Rusya', ['Fransa ve İtalya', 'İngiltere ve Belçika', 'Rusya ve Sırbistan'], '1907 İngiliz-Rus Antlaşması (St. Petersburg Sözleşmesi) ile Fransa\'nın her iki müttefiki birbiriyle uzlaşmış ve Üçlü İtilaf halkası tamamlanmıştır.'),
  ('19. yüzyıl sonunda silahlanma yarışını sınırlandırmak ve uyuşmazlıkların barışçıl çözüm yollarını aramak üzere 1899 yılında Birinci Lahey Barış Konferansı\'nın toplanması çağrısını yapan hükümdar kimdir?', 'Rus Çarı II. Nikolay', ['İngiltere Kraliçesi Victoria', 'Alman İmparatoru II. Wilhelm', 'Avusturya İmparatoru Franz Joseph'], 'Ağustos 1898\'de Rus Dışişleri Bakanı Muravyov aracılığıyla yayımlanan Çar II. Nikolay\'ın sirküleri üzerine 1899\'da Hollanda\'nın Lahey kentinde konferans toplanmıştır.'),
  ('1899 ve 1907 yıllarında düzenlenen iki büyük uluslararası barış ve savaş hukuku konferansına ev sahipliği yapan Hollanda şehri hangisidir?', 'Lahey', ['Amsterdam', 'Rotterdam', 'Utrecht'], 'Hollanda Kraliçesi Wilhelmina\'nın ev sahipliğinde barış konferansları 1899 ve 1907 yıllarında Lahey\'de toplanmıştır.'),
  ('1907 yılında toplanan İkinci Lahey Barış Konferansı\'nın ilk girişimini başlatan ve ardından diplomatik nezaket gereği daveti yeniden Çar II. Nikolay\'a bırakan ABD Başkanı kimdir?', 'Theodore Roosevelt', ['Woodrow Wilson', 'William McKinley', 'Abraham Lincoln'], '1904\'te ABD Başkanı Theodore Roosevelt ikinci konferans fikrini ortaya atmış, Rus-Japon Savaşı bitince resmi davet yine Çar II. Nikolay tarafından yapılmıştır.'),
  ('1815 Viyana Kongresi\'nde köle ticareti konusunda büyük devletlerin kabul ettiği ilkesel bildiri neyi öngörmekteydi?', 'Atlantik köle ticaretinin insanlık ve genel ahlak ilkelerine aykırı olduğunun kınanarak kaldırılması yönünde irade beyan edilmesini', ['Köle ticaretinin yalnızca Akdeniz limanları arasında serbest bırakılmasını', 'Afrika\'daki tüm plantasyonların doğrudan Viyana\'dan yönetilen bir şirkete devredilmesini', 'Köle gemilerinden alınan gümrük vergilerinin Avrupa Uyumu bütçesine aktarılmasını'], 'İngiltere\'nin (Castlereagh) yoğun diplomatik baskısıyla Viyana Kongresi\'nde köle ticaretini kınayan tarihi bir bildiri kabul edilmiştir.'),
  ('19. yüzyıl diplomasi dilinde büyük güçlerin küçük devletlerin rızasına bakmaksızın sınır ve toprak takası yaparak aralarındaki güç eşitliğini korumasına ne ad verilmiştir?', 'Tazmin (Denkleştirme / Compensation) İlkesi', ['Ulusların Kendi Kaderini Tayin İlkesi', 'Açık Diplomasi İlkesi', 'Saldırmazlık ve Yatıştırma İlkesi'], 'Viyana Kongresi\'nde meşruiyet ilkesinin yanı sıra büyük güçler arasındaki dengeyi korumak için toprak ve nüfus bakımından "denkleştirme (compensation)" uygulanmıştır.'),
  ('İngiltere\'nin 1878\'de Kıbrıs\'ın yönetimini devralmasının hemen ardından 1882 yılında "Urabi Paşa Ayaklanması"nı ve düzeni sağlama gerekçesini öne sürerek işgal ettiği Osmanlı toprağı neresidir?', 'Mısır', ['Cezayir', 'Trablusgarp', 'Yemen'], 'Süveyş Kanalı ve Hindistan yolunun güvenliğini kontrol altına almak isteyen İngiltere, 1882\'de İskenderiye\'yi bombalayarak Mısır\'ı işgal etmiştir.'),
  ('1899 ve 1907 Lahey Sözleşmeleri ile düzenlenen "savaş esirlerine insanca muamele edilmesi ve sivil halkın korunması" kuralları uluslararası hukukun hangi dalının temelini oluşturmuştur?', 'Uluslararası İnsancıl Hukuk', ['Uluslararası Ticaret ve Şirketler Hukuku', 'Diplomatik Dokunulmazlık ve Konsolosluk Hukuku', 'Uluslararası Deniz Yatağı ve Kıta Sahanlığı Hukuku'], 'Cenevre Sözleşmeleri ile birlikte 1899 ve 1907 Lahey Kara Savaşı Tüzükleri, çatışma sırasındaki yöntem ve araçları sınırlayan insancıl hukukun (Lahey Hukuku) ana gövdesini oluşturur.'),
  ('1907 yılı itibarıyla Avrupa\'da kesinleşen iki büyük blok olan "Üçlü İttifak" ve "Üçlü İtilaf" devletleri hangi seçenekte doğru eşleştirilmiştir?', 'Üçlü İttifak: Almanya, Avusturya-Macaristan, İtalya — Üçlü İtilaf: İngiltere, Fransa, Rusya', ['Üçlü İttifak: Almanya, Rusya, Osmanlı — Üçlü İtilaf: İngiltere, Fransa, İtalya', 'Üçlü İttifak: Avusturya, İspanya, Almanya — Üçlü İtilaf: İngiltere, ABD, Japonya', 'Üçlü İttifak: Almanya, Fransa, Belçika — Üçlü İtilaf: Rusya, Avusturya, Sırbistan'], '1882\'de kurulan Üçlü İttifak (Almanya, Avusturya-Macaristan, İtalya) karşısında 1894, 1904 ve 1907 halkalarıyla Üçlü İtilaf (Fransa, Rusya, İngiltere) şekillenmiştir.'),
  ('1912 yılında Rusya\'nın diplomatik teşviki ve arabuluculuğuyla Osmanlı Devleti\'ne ve olası Avusturya yayılmasına karşı kurulan dörtlü ittifak sistemi hangisidir?', 'Balkan Birliği (Bulgaristan, Sırbistan, Yunanistan, Karadağ)', ['Küçük Antant (Çekoslovakya, Romanya, Yugoslavya)', 'Sadabat Paktı (Türkiye, İran, Irak, Afganistan)', 'Kuzey Deniz Birliği (İsveç, Danimarka, Norveç, Rusya)'], '1912 baharında Rus diplomasisinin yönlendirmesiyle Sırbistan, Bulgaristan, Yunanistan ve Karadağ arasında kurulan ittifak ağı Birinci Balkan Savaşı\'nı başlatmıştır.'),
  ('1774 Küçük Kaynarca Antlaşması ile Rusya\'ya verilen ticari ayrıcalıklardan biri olan "en çok gözetilen ulus" statüsü somut olarak hangi devletlerin yararlandığı kapitülasyon haklarına atıf yapmıştır?', 'İngiltere ve Fransa', ['İspanya ve Portekiz', 'İsveç ve Danimarka', 'Prusya ve Lehistan'], 'Küçük Kaynarca Antlaşması ile Rusya, Osmanlı ülkesinde en ziyade müsaadeye mazhar devletler olan İngiltere ve Fransa\'ya tanınan ticari ayrıcalıklardan yararlanma hakkı elde etmiştir.'),
  ('I. Dünya Savaşı devam ederken 3 Mart 1918\'de Sovyet Rusya\'nın savaştan çekildiği ve Osmanlı Devleti\'nin Elviye-i Selase\'yi geri aldığı antlaşma hangisidir?', 'Brest-Litovsk Antlaşması', ['Saint-Germain Barış Antlaşması', 'Neuilly Barış Antlaşması', 'Trianon Barış Antlaşması'], 'Brest-Litovsk Antlaşması ile Sovyet Rusya savaştan çekilmiş ve Kars, Ardahan ile Batum Osmanlı Devleti\'ne iade edilmiştir.'),
  ('I. Dünya Savaşı sonunda İtilaf Devletleri ile Almanya arasında 28 Haziran 1919 tarihinde imzalanan barış antlaşması hangisidir?', 'Versay Antlaşması', ['Saint-Germain Antlaşması', 'Trianon Antlaşması', 'Sevr Antlaşması'], 'Almanya ile İtilaf Devletleri arasında Paris Barış Konferansı sonucunda 28 Haziran 1919\'da Versay Sarayı\'nda Versay Antlaşması imzalanmıştır.'),
  ('Versay Antlaşması uyarınca kömür madenleri Fransa\'ya bırakılan ve on beş yıl sonra halk oylamasıyla geleceği belirlenecek olan Alman bölgesi hangisidir?', 'Saar Havzası', ['Ruhr Havzası', 'Bavyera Bölgesi', 'Vestfalya Bölgesi'], 'Saar Havzası on beş yıllığına Milletler Cemiyeti idaresine bırakılmış, 1935\'teki plebisit sonucunda yeniden Almanya\'ya katılmıştır.'),
  ('Türk Kurtuluş Savaşı\'nın silahlı mücadele dönemini sona erdiren ve 11 Ekim 1922 tarihinde imzalanan ateşkes antlaşması hangisidir?', 'Mudanya Ateşkes Antlaşması', ['Mondros Ateşkes Antlaşması', 'Rethondes Ateşkes Antlaşması', 'Villa Giusti Ateşkes Antlaşması'], 'Büyük Taarruz\'un zaferle sonuçlanmasının ardından 11 Ekim 1922\'de imzalanan Mudanya Ateşkes Antlaşması ile Kurtuluş Savaşı\'nın askeri safhası bitmiştir.'),
  ('Mudanya Ateşkes Antlaşması görüşmelerinde Türkiye Büyük Millet Meclisi Hükümeti\'ni temsil eden heyetin başkanı kimdir?', 'İsmet Paşa', ['Fevzi Paşa', 'Kazım Karabekir Paşa', 'Ali Fuat Paşa'], 'Batı Cephesi Komutanı İsmet Paşa (İnönü), Mudanya Konferansı\'nda TBMM Hükümeti\'ni başarıyla temsil etmiş ve bu başarısı Lozan\'a başdelege seçilmesini sağlamıştır.'),
  ('Yeni Türk Devleti\'nin bağımsızlığını ve egemenliğini uluslararası alanda tescil eden 24 Temmuz 1923 tarihli kurucu antlaşma hangisidir?', 'Lozan Barış Antlaşması', ['Ankara İtilafnamesi', 'Moskova Dostluk Antlaşması', 'Kars Antlaşması'], '24 Temmuz 1923\'te imzalanan Lozan Barış Antlaşması, Türkiye Cumhuriyeti\'nin uluslararası alanda tanınmasını sağlayan kurucu belgedir.'),
  ('Mustafa Kemal Paşa\'nın Lozan\'a giden Türk heyetinden kesinlikle taviz verilmemesini istediği iki temel konu aşağıdakilerden hangisidir?', 'Kapitülasyonların kaldırılması ve Ermeni yurdu iddialarının reddi', ['Musul vilayetinin alınması ve Batı Trakya\'da halk oylaması yapılması', 'Boğazlar Komisyonu\'nun kaldırılması ve On İki Ada\'nın Türkiye\'ye verilmesi', 'Osmanlı borçlarının silinmesi ve Hatay\'ın anavatana derhal katılması'], 'TBMM ve Mustafa Kemal Paşa, tam bağımsızlık ilkesiyle bağdaşmayan kapitülasyonlar ve Anadolu bütünlüğünü hedef alan Ermeni yurdu konularında kesinlikle taviz verilmemesini emretmiştir.'),
  ('I. Dünya Savaşı sonrasında dünya barışını korumak amacıyla ABD Başkanı Woodrow Wilson\'ın 14 İlkeleri doğrultusunda 10 Ocak 1920\'de kurulan uluslararası örgüt hangisidir?', 'Milletler Cemiyeti', ['Birleşmiş Milletler', 'Avrupa Konseyi', 'Kuzey Atlantik Antlaşması Örgütü'], 'Cemiyet-i Akvam (Milletler Cemiyeti), Paris Barış Konferansı\'nda kabul edilen sözleşmeyle 1920 yılında uluslararası barış ve güvenliği korumak üzere kurulmuştur.'),
  ('Milletler Cemiyeti\'nin genel merkezi İsviçre\'nin hangi şehrinde kurulmuştur?', 'Cenevre', ['Zürih', 'Lozan', 'Basel'], 'Tarafsızlık statüsü nedeniyle İsviçre\'nin Cenevre kenti Milletler Cemiyeti\'nin merkezi olarak seçilmiştir.'),
  ('Milletler Cemiyeti bünyesinde devletler arası hukuki uyuşmazlıkları çözmek amacıyla Lahey\'de kurulan yargı organının adı nedir?', 'Milletlerarası Daimi Adalet Divanı', ['Avrupa İnsan Hakları Mahkemesi', 'Uluslararası Ceza Mahkemesi', 'Nürnberg Uluslararası Askeri Mahkemesi'], 'Cemiyet Misakı\'nın 14. maddesi uyarınca 1922\'de Lahey\'de çalışmalarına başlayan Milletlerarası Daimi Adalet Divanı, Bozkurt-Lotus davası gibi önemli uyuşmazlıklara bakmıştır.'),
  ('Almanya\'nın batı sınırlarını güvence altına alarak Avrupa\'da yumuşama ("Locarno Ruhu") dönemini başlatan antlaşmalar Ekim 1925\'te hangi ülkede imzalanmıştır?', 'İsviçre', ['Belçika', 'Hollanda', 'Lüksemburg'], 'Locarno Antlaşmaları, İsviçre\'nin İtalyanca konuşulan Ticino kantonundaki Locarno kentinde Ekim 1925\'te müzakere edilmiş ve Aralık 1925\'te Londra\'da resmen imzalanmıştır.'),
  ('Ulusal politikanın bir aracı olarak savaşı yasaklayan ve 27 Ağustos 1928\'de Paris\'te imzalanan uluslararası antlaşma hangisidir?', 'Briand-Kellogg Paktı', ['Rapallo Antlaşması', 'Dawes Planı', 'Young Planı'], 'Fransa Dışişleri Bakanı Aristide Briand ile ABD Dışişleri Bakanı Frank B. Kellogg\'un girişimiyle hazırlanan Paris Paktı (Briand-Kellogg Paktı) savaşı ulusal siyaset aracı olmaktan çıkarmayı hedeflemiştir.'),
  ('I. Dünya Savaşı sonrasında Almanya\'nın savaş tazminatı ödemelerini yeniden yapılandırmak amacıyla 1924 yılında ABD\'li bir bankacının başkanlığında hazırlanan ekonomik plan hangisidir?', 'Dawes Planı', ['Marshall Planı', 'Truman Doktrini', 'Schuman Planı'], 'Charles G. Dawes başkanlığındaki komitenin hazırladığı 1924 Dawes Planı, Almanya\'nın tazminat taksitlerini ödeme kapasitesine göre düzenlemiş ve Amerikan kredileriyle Alman ekonomisini rahatlatmıştır.'),
  ('Lozan Barış Antlaşması\'na göre Türkiye ile Yunanistan arasındaki kara sınırını belirleyen doğal coğrafi unsur hangisidir?', 'Meriç Nehri', ['Tunca Nehri', 'Arda Nehri', 'Vardar Nehri'], 'Mudanya ve Lozan antlaşmaları uyarınca Karaağaç çıkıntısı dışında Türkiye-Yunanistan sınırı Meriç Nehri yatağı olarak belirlenmiştir.'),
  ('Lozan Barış Konferansı hangi ülkenin ev sahipliğinde toplanmıştır?', 'İsviçre', ['Fransa', 'İngiltere', 'İtalya'], 'Tarafsız bir ülke olması sebebiyle barış konferansı İsviçre\'nin Lozan (Lausanne) şehrinde toplanmıştır.'),
  ('Versay Antlaşması ile Almanya\'nın denizaşırı sömürgelerinin tamamını kaybetmesi ekonomik açıdan öncelikle hangi sonucu doğurmuştur?', 'Ucuz hammadde kaynaklarına ve dış pazarlara doğrudan erişimini yitirmesi', ['Avrupa kıtasındaki tüm demiryolu hatlarının İngiltere\'ye devredilmesi', 'Alman markının altın standardına bağlanarak değerinin aşırı yükselmesi', 'Tarım arazilerinin tamamının komşu devletler arasında paylaştırılması'], 'Almanya\'nın Afrika ve Pasifik\'teki sömürgeleri Milletler Cemiyeti mandası adı altında İngiltere, Fransa, Japonya, Belçika ve İngiliz dominyonları arasında paylaşılmıştır.'),
  ('9 Şubat 1934 tarihinde Atina\'da imzalanan Balkan Antantı\'na katılan dört kurucu devlet aşağıdakilerden hangisidir?', 'Türkiye, Yunanistan, Yugoslavya ve Romanya', ['Türkiye, Bulgaristan, Arnavutluk ve Yunanistan', 'Türkiye, Romanya, Macaristan ve Yugoslavya', 'Türkiye, Yunanistan, İtalya ve Arnavutluk'], 'Almanya ve İtalya\'nın yayılmacı politikalarına karşı sınır güvenliğini korumak amacıyla Türkiye, Yunanistan, Yugoslavya ve Romanya 1934\'te Balkan Antantı\'nı imzalamıştır.'),
  ('İtalya\'nın Habeşistan\'ı işgali sonrasında Orta Doğu\'da güvenliği sağlamak amacıyla 8 Temmuz 1937\'de Tahran\'da imzalanan Sadabat Paktı\'nın üyeleri hangi seçenekte doğru verilmiştir?', 'Türkiye, İran, Irak ve Afganistan', ['Türkiye, Suriye, Irak ve Mısır', 'Türkiye, İran, Pakistan ve Suudi Arabistan', 'Türkiye, Ürdün, Lübnan ve Afganistan'], '8 Temmuz 1937\'de İran\'ın başkenti Tahran\'daki Sadabat Sarayı\'nda Türkiye, İran, Irak ve Afganistan arasında dörtlü saldırmazlık ve dostluk paktı imzalanmıştır.'),
  ('II. Dünya Savaşı\'nın son aylarında (Nisan-Haziran 1945) elli devletin katılımıyla toplanarak Birleşmiş Milletler Antlaşması\'nı hazırlayan uluslararası konferans hangisidir?', 'San Francisco Konferansı', ['Potsdam Konferansı', 'Kazablanka Konferansı', 'Tahran Konferansı'], '25 Nisan - 26 Haziran 1945 tarihleri arasında toplanan San Francisco Konferansı\'nda BM Şartı imzalanmış ve 24 Ekim 1945\'te yürürlüğe girerek Birleşmiş Milletler resmen kurulmuştur.'),
  ('Birleşmiş Milletler Güvenlik Konseyinde veto hakkına sahip beş daimi üye devlet (P5) hangi seçenekte eksiksiz verilmiştir?', 'ABD, İngiltere, Fransa, Rusya (SSCB) ve Çin', ['ABD, İngiltere, Almanya, Japonya ve Rusya', 'ABD, Fransa, Almanya, Hindistan ve Brezilya', 'İngiltere, Fransa, İtalya, Kanada ve Çin'], 'II. Dünya Savaşı\'nın galip güçleri olan ABD, Birleşik Krallık, Fransa, Sovyetler Birliği (ardılı Rusya Federasyonu) ve Çin BM Güvenlik Konseyinin veto yetkili beş daimi üyesidir.'),
  ('Birleşmiş Milletler Genel Kurulunun 10 Aralık 1948 tarihinde Paris\'te kabul ettiği temel insan hakları belgesi aşağıdakilerden hangisidir?', 'İnsan Hakları Evrensel Beyannamesi', ['Avrupa İnsan Hakları Sözleşmesi', 'Helsinki Nihai Senedi', 'Cenevre Savaş Hukuku Sözleşmeleri'], 'Eleanor Roosevelt başkanlığındaki komisyonun hazırladığı İnsan Hakları Evrensel Beyannamesi, 10 Aralık 1948\'de BM Genel Kurulunda kabul edilmiştir.'),
  ('Soğuk Savaş döneminde Sovyet yayılmacılığına karşı Batı bloğunun ortak savunmasını sağlamak üzere 4 Nisan 1949\'da Washington\'da kurulan askeri ittifak hangisidir?', 'Kuzey Atlantik Antlaşması Örgütü', ['Varşova Paktı', 'Avrupa Ekonomik Topluluğu', 'Batı Avrupa Birliği'], 'ABD, Kanada ve on Batı Avrupa ülkesi tarafından 4 Nisan 1949\'da imzalanan Kuzey Atlantik Antlaşması ile NATO kurulmuştur.'),
  ('Türkiye Cumhuriyeti hangi ülkedeki BM harekâtına tugay düzeyinde asker göndererek gösterdiği başarının ardından 18 Şubat 1952\'de Yunanistan ile birlikte NATO\'ya üye olmuştur?', 'Kore', ['Vietnam', 'Mısır', 'Kongo'], 'Türkiye 1950\'de Kore Savaşı\'na Şimal Yıldızı (Türk Tugayı) birliğini göndererek Batı ittifakı içindeki stratejik değerini kanıtlamış ve 1952\'de Yunanistan ile eş zamanlı olarak NATO\'ya katılmıştır.'),
  ('İnsan hakları, hukukun üstünlüğü ve çoğulcu demokrasiyi korumak amacıyla 5 Mayıs 1949\'da Londra Antlaşması ile kurulan ve merkezi Strazburg\'da bulunan Avrupa örgütü hangisidir?', 'Avrupa Konseyi', ['Avrupa Kömür ve Çelik Topluluğu', 'Avrupa Ekonomik Topluluğu', 'Avrupa Güvenlik ve İşbirliği Teşkilatı'], 'Avrupa Konseyi (Council of Europe) 5 Mayıs 1949\'da on Batı Avrupa devleti tarafından kurulmuş olup Avrupa Birliği\'nden ayrı bir hükümetlerarası insan hakları ve demokrasi örgütüdür.'),
  ('9 Mayıs 1950\'de yayımladığı bildirgeyle Fransız ve Alman kömür-çelik üretimini ortak bir yüksek otorite altına almayı önererek bugünkü Avrupa Birliği\'nin temelini atan Fransız Dışişleri Bakanı kimdir?', 'Robert Schuman', ['Charles de Gaulle', 'Georges Bidault', 'Aristide Briand'], 'Jean Monnet\'nin fikri hazırlığını yaptığı ve 9 Mayıs 1950\'de Robert Schuman tarafından açıklanan Schuman Bildirgesi, Avrupa bütünleşmesinin başlangıcı (Avrupa Günü) kabul edilir.'),
  ('18 Nisan 1951\'de Paris Antlaşması ile kurulan Avrupa Kömür ve Çelik Topluluğunun (AKÇT) "Altılar" olarak bilinen kurucu üyeleri hangi seçenekte doğru verilmiştir?', 'Fransa, Batı Almanya, İtalya, Belçika, Hollanda ve Lüksemburg', ['Fransa, İngiltere, İspanya, Portekiz, İtalya ve Yunanistan', 'Batı Almanya, Avusturya, İsviçre, Danimarka, İsveç ve Norveç', 'Fransa, Batı Almanya, İngiltere, İrlanda, Belçika ve Hollanda'], 'Fransa, Federal Almanya, İtalya ve Benelüks ülkeleri (Belçika, Hollanda, Lüksemburg) 1951 Paris Antlaşması ile AKÇT\'yi, 1957 Roma Antlaşmaları ile AET ve Euratom\'u kurmuştur.'),
  ('Soğuk Savaş\'ın iki kutuplu düzeninde Asya ve Afrika\'nın yeni bağımsız ülkelerini bir araya getirerek Bağlantısızlar Hareketi\'ne zemin hazırlayan Nisan 1955 tarihli konferans hangi ülkede toplanmıştır?', 'Endonezya', ['Hindistan', 'Mısır', 'Yugoslavya'], '18-24 Nisan 1955 tarihlerinde Endonezya\'nın Bandung şehrinde 29 Asya ve Afrika ülkesinin katılımıyla toplanan Bandung Konferansı, Üçüncü Dünya dayanışmasının simgesi olmuştur.'),
  ('Bağlantısızlar Hareketi\'nin (Non-Aligned Movement) resmen kurulduğu Eylül 1961 tarihli ilk zirve toplantısı hangi şehirde gerçekleştirilmiştir?', 'Belgrad', ['Kahire', 'Yeni Delhi', 'Cakarta'], 'Bandung Konferansı düşünsel zemini hazırlamış, Josip Broz Tito\'nun ev sahipliğinde 1-6 Eylül 1961\'de Yugoslavya\'nın başkenti Belgrad\'da düzenlenen zirveyle Bağlantısızlar Hareketi resmen kurulmuştur.'),
  ('Soğuk Savaş yıllarında Orta Doğu\'yu Sovyet nüfuzuna karşı korumak amacıyla Şubat 1955\'te Türkiye ve Irak arasında imzalanan, ardından İngiltere, Pakistan ve İran\'ın katıldığı ittifak hangisidir?', 'Bağdat Paktı', ['Sadabat Paktı', 'Balkan Antantı', 'Varşova Paktı'], '1955\'te kurulan Bağdat Paktı\'ndan 1958 darbesi sonrasında Irak\'ın çekilmesi üzerine örgütün merkezi Ankara\'ya taşınmış ve adı Merkezi Antlaşma Örgütü (CENTO) olarak değiştirilmiştir.'),
  ('Birleşmiş Milletler örgütünün genel merkezi ABD\'nin hangi şehrinde yer almaktadır?', 'New York', ['Washington', 'San Francisco', 'Cenevre'], 'BM Şartı San Francisco\'da imzalanmış, örgütün kalıcı genel merkezi ise New York\'ta (Manhattan) inşa edilmiştir.'),
  ('1930\'lu yıllarda Türkiye\'nin hem batısında Balkan Antantı\'na hem de doğusunda Sadabat Paktı\'na öncülük etmesinin ortak dış politika hedefi nedir?', 'II. Dünya Savaşı tehlikesi yaklaşırken Türkiye\'nin çevresinde barış ve güvenlik kuşağı oluşturmak', ['Osmanlı İmparatorluğu\'nun Misak-ı Milli dışında kalan eski eyaletlerini yeniden sınırlarına katmak', 'Milletler Cemiyeti\'ne alternatif olarak Ankara merkezli yeni bir küresel örgüt kurmak', 'Balkan ve Orta Doğu ülkeleri arasında tek para birimine dayalı ortak pazar oluşturmak'], 'İtalya ve Almanya\'nın revizyonist yayılmacılığı karşısında Türkiye sınırlarını güvence altına almak ve bölgesel barışı korumak için her iki paktın kuruluşunda kilit rol oynamıştır.'),
  ('Birleşmiş Milletler\'in yargı organı olan Uluslararası Adalet Divanı hangi ülkenin Lahey (Den Haag) şehrinde görev yapmaktadır?', 'Hollanda', ['İsviçre', 'Belçika', 'Lüksemburg'], 'BM\'nin New York dışında bulunan tek ana organı olan Uluslararası Adalet Divanı, selefi Milletlerarası Daimi Adalet Divanı gibi Hollanda\'nın Lahey kentindeki Barış Sarayı\'nda faaliyet gösterir.'),
  ('II. Dünya Savaşı sonrasında Avrupa\'da kurulan örgütlerden hangisi askeri savunma veya gümrük birliği amacıyla değil, doğrudan insan hakları ve hukuk devleti standartlarını geliştirmek amacıyla kurulmuştur?', 'Avrupa Konseyi', ['Kuzey Atlantik Antlaşması Örgütü', 'Avrupa Kömür ve Çelik Topluluğu', 'Varşova Paktı'], '1949\'da kurulan Avrupa Konseyi askeri ve ekonomik bütünleşme konularını kapsam dışı bırakarak demokrasi, insan hakları ve hukukun üstünlüğü alanlarında uzmanlaşmıştır.'),
  ('Lozan Barış Antlaşması ile kaldırılan ve yabancı devlet vatandaşlarına Osmanlı topraklarında ticari, mali ve adli ayrıcalıklar tanıyan uygulamaya ne ad verilir?', 'Kapitülasyonlar', ['Mübadele', 'Moratoryum', 'Plebisit'], 'Yüzyıllar boyunca Osmanlı ekonomisini ve yargı bağımsızlığını zedeleyen kapitülasyonlar, Lozan Barış Antlaşması\'nın 28. maddesiyle bütün sonuçlarıyla birlikte kesin olarak kaldırılmıştır.'),
  ('I. Dünya Savaşı sonunda Bulgaristan ile İtilaf Devletleri arasında 27 Kasım 1919 tarihinde imzalanan ve Bulgaristan\'ın Ege Denizi ile bağlantısını kesen antlaşma hangisidir?', 'Neuilly Antlaşması', ['Trianon Antlaşması', 'Saint-Germain Antlaşması', 'Versay Antlaşması'], 'Paris yakınlarındaki Neuilly-sur-Seine kasabasında imzalanan Neuilly Antlaşması ile Bulgaristan Batı Trakya\'yı kaybederek Ege Denizi çıkışını yitirmiş ve iki savaş arası dönemde revizyonist politika izlemiştir.'),
];
